import React, { useState } from 'react';
import { View, Dimensions } from 'react-native';
import StarsGlobe from '@/components/StarsGlobe';

const { width } = Dimensions.get('window');

export default function App() {
  const [mode, setMode] = useState<'globe' | 'flat'>('globe');
  const [country, setCountry] = useState<string | null>('IN');

  return (
    <View style={{ flex: 1, backgroundColor: '#030712', justifyContent: 'center', alignItems: 'center' }}>
      <StarsGlobe
        mode={mode}
        onModeChange={setMode}
        size={Math.min(width - 20, 390)}
        selectedCountryCode={country}
        onSelectCountry={(c) => setCountry(c?.code ?? null)}
      />
    </View>
  );
}
